import json,urllib.request
base='http://127.0.0.1:17448'
out={}
try:
 d=json.loads(urllib.request.urlopen(base+'/api/supervisor-watchdog/agent-assignments?chatId=agent-pc-control',timeout=10).read().decode('utf-8'))
 rows=[x for x in d.get('assignments',[]) if x.get('id') in ['5dc21cfa-6bad-4df8-a493-99d0ece5a248','b1314ed6-5b22-4cbf-8865-e044b4bd683f']]
 out['assignments']=[{k:x.get(k) for k in ['id','state','lastPreflightReason','lastDiagnostic','dispatchCount','dispatchSubmitAttempted','dispatchTargetId','updatedAt','completedAt']} for x in rows]
except Exception as e:
 out['assignments_error']=type(e).__name__+': '+str(e)
try:
 d=json.loads(urllib.request.urlopen(base+'/api/projects/control-plane/operations',timeout=10).read().decode('utf-8'))
 ops=d.get('operations') or []
 out['operation']=[x for x in ops if x.get('operationId')=='coord-20261007-native-r39-direct-01']
except Exception as e:
 out['operations_error']=type(e).__name__+': '+str(e)
print(json.dumps(out,ensure_ascii=True,separators=(',',':')))
